100	export async function infoCommand(
101		infoArgs: StrictYargsOptionsToInterface<typeof infoYargs>,
102		_config: Config
103	) {
104		if (!infoArgs.ID) {
105			throw new Error(
106				"You must provide an ID. Use 'wrangler containers list` to view your containers."
107			);
108		}
109		if (isNonInteractiveOrCI()) {
110			const application = await ApplicationsService.getApplication(infoArgs.ID);
111			logger.json(application);
112			return;
113		}
114		const [application, err] = await wrap(
115			ApplicationsService.getApplication(infoArgs.ID)
116		);
117		if (err) {
118			throw new UserError(
119				`There has been an internal error requesting your containers.\n ${err.message}`
120			);
121		}
122	
123		const applicationDetails = {
124			label: `${application.name} (${application.created_at})`,
125			details: YAML.stringify(application).split("\n"),
126			value: application.id,
127		};
128		await inputPrompt({
129			type: "list",
130			question: "Container",
131			options: [applicationDetails],
132			label: "Exiting",
133		});
134	}
