221	async function listContainersAndChoose(
222		applications: ListApplications
223	): Promise<Application> {
224		const getLabels = (a: Application) => {
225			const labels = a.configuration.labels ?? [];
226			if (!labels || labels.length == 0) {
227				return [];
228			}
229			const out = labels.map((l) => `        ${dim(l.name)}: ${dim(l.value)}`);
230			return `Labels:\n` + out.join(",\n");
231		};
232	
233		const application = await processArgument({}, "applicationId", {
234			type: "list",
235			question: "Your Containers",
236			helpText:
237				"Get more information by selecting a container with the enter/return key",
238			options: applications.map((i) => ({
239				label: i.name,
240				value: i.id,
241				details: [
242					`Id: ${dim(`${i.id}`)}`,
243					`Instances: ${dim(`${i.instances}`)}`,
244					`Image: ${dim(i.configuration.image)}`,
245					...(getLabels(i) ?? []),
246				],
247			})),
248			label: "container",
249		});
250		// eslint-disable-next-line @typescript-eslint/no-non-null-assertion
251		return applications.find((a) => a.id === application)!;
252	}
