139	function rowsToJsonOutput(rows: InstanceRow[]): Record<string, unknown>[] {
140		const hasDurableObjects = rows.some((r) => r.durableObject);
141	
142		if (hasDurableObjects) {
143			return rows.map((row) => {
144				const state = row.instance
145					? deriveInstanceState(row.instance)
146					: "inactive";
147				return {
148					id: row.durableObject?.id ?? row.instance?.id ?? null,
149					name: row.durableObject?.name ?? null,
150					state,
151					location: row.instance?.location ?? null,
152					version: row.instance?.app_version ?? null,
153					created:
154						row.instance?.created_at ?? row.durableObject?.assigned_at ?? null,
155				};
156			});
157		}
158	
159		return rows.map((row) => {
160			const state = row.instance ? deriveInstanceState(row.instance) : "unknown";
161			return {
162				id: row.instance?.id ?? null,
163				state,
164				location: row.instance?.location ?? null,
165				version: row.instance?.app_version ?? null,
166				created: row.instance?.created_at ?? null,
167			};
168		});
169	}
170	
171	function renderTable(rows: InstanceRow[]): void {
172		const hasDurableObjects = rows.some((r) => r.durableObject);
173	
174		if (hasDurableObjects) {
175			logger.table(
176				rows.map((row) => {
177					const state = row.instance
178						? deriveInstanceState(row.instance)
179						: "inactive";
180					return {
181						INSTANCE: row.durableObject?.id ?? row.instance?.id ?? "-",
182						NAME: row.durableObject?.name ?? "-",
183						STATE: colorState(state),
184						LOCATION: row.instance?.location ?? "-",
185						VERSION: row.instance ? String(row.instance.app_version) : "-",
186						CREATED:
187							row.instance?.created_at ?? row.durableObject?.assigned_at ?? "-",
188					};
189				})
190			);
191		} else {
192			logger.table(
193				rows.map((row) => {
194					const state = row.instance
