/**
 * Derive a container's high-level state from its health instance counters.
 * The priority order is: degraded > provisioning > active > ready.
 */
export function deriveContainerState(app: DashApplication): string {
	const { active, failed, starting, scheduling } = app.health.instances;
	if (failed > 0) {
		return "degraded";
	}
	if (starting > 0 || scheduling > 0) {
		return "provisioning";
	}
	if (active > 0) {
		return "active";
	}
	return "ready";
}

function colorContainerState(state: string): string {
	switch (state) {
		case "active":
			return green(state);
		case "degraded":
			return red(state);
		default:
			return state;
	}
}

function applicationToJson(app: DashApplication): Record<string, unknown> {
	return {
		id: app.id,
		name: app.name,
		state: deriveContainerState(app),
		instances: app.instances,
		image: app.image,
		version: app.version,
		updated_at: app.updated_at,
		created_at: app.created_at,
	};
}

function renderContainersTable(apps: DashApplication[]): void {
	logger.table(
		apps.map((app) => {
			const state = deriveContainerState(app);
			return {
				ID: app.id,
				NAME: app.name,
				STATE: colorContainerState(state),
				"LIVE INSTANCES": String(app.health.instances.active),
				"LAST MODIFIED": app.updated_at,
			};
		})
	);
}

