147	export function deriveContainerState(app: DashApplication): string {
148		const { active, failed, starting, scheduling } = app.health.instances;
149		if (failed > 0) {
150			return "degraded";
151		}
152		if (starting > 0 || scheduling > 0) {
153			return "provisioning";
154		}
155		if (active > 0) {
156			return "active";
157		}
158		return "ready";
159	}
